// Port of test14.py.
//
//   parser = argparse.ArgumentParser()
//   parser.add_argument('--a', type=int, required=True)
//   parser.add_argument('--b', type=int, required=True)
//   parser.add_argument('--c', type=str, required=True)
//   args = parser.parse_args()
//   encoded_int1 = base58.b58encode_int(args.a)
//   encoded_int2 = base58.b58encode_int(args.b)
//   decoded_int  = base58.b58decode_int(args.c)
//   print(encoded_int1); print(encoded_int2); print(decoded_int)
//
// Both integers are encoded before the string is decoded, so a bad --c leaves
// stdout completely empty — nothing is printed until all three values exist.

import { basename } from 'node:path';

import { ArgumentParser, SystemExit, types } from './lib/argparse/index.mjs';
import * as base58 from './lib/base58/index.mjs';
import { PyError } from './lib/pyerrors.mjs';
import { pyPrint } from './lib/pyprint.mjs';
import { writeTraceback } from './lib/pytraceback.mjs';

// argparse defaults prog to basename(sys.argv[0]); the Node equivalent is the
// script path in argv[1].
const PROG = basename(process.argv[1] ?? 'test14.mjs');

// Mirrors the `decoded_int = ...` statement the reference traceback points at.
// The column span is the one baked into the compiled code object, covering
// `base58.b58decode_int(args.c)`.
const DECODE_CALL_SITE = { line: 12, colStart: 14, colEnd: 42 };

function main(argv) {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument(['--a'], { type: types.int, required: true });
  parser.addArgument(['--b'], { type: types.int, required: true });
  parser.addArgument(['--c'], { type: types.str, required: true });
  const args = parser.parseArgs(argv);

  const encodedInt1 = base58.b58encode_int(args.a); // 编码第一个整数
  const encodedInt2 = base58.b58encode_int(args.b); // 编码第二个整数
  const decodedInt = base58.b58decode_int(args.c); // 解码为整数

  pyPrint(encodedInt1);
  pyPrint(encodedInt2);
  pyPrint(decodedInt);
}

try {
  main(process.argv.slice(2));
} catch (error) {
  if (error instanceof SystemExit) {
    // argparse already wrote usage/help; returning normally lets Node drain
    // stdout and stderr before the status is applied.
    process.exitCode = error.code;
  } else if (error instanceof PyError) {
    writeTraceback(error, DECODE_CALL_SITE);
    process.exitCode = 1;
  } else {
    throw error;
  }
}

// Faithful port of `int(str)` for base 10, returning a BigInt so arbitrarily
// large values behave like Python's unbounded ints.
//
// CPython first runs the text through PyUnicode_TransformDecimalAndSpaceToASCII,
// which folds every White_Space character to a plain space and rewrites every
// Unicode decimal digit as its ASCII counterpart. Only then does the ASCII
// scanner run, and that scanner accepts a narrower whitespace set. This is why
// '١٠', '１０' and '\xa010' all parse while '\x1c10' and '﻿10' do not.

import { PyValueError } from './pyerrors.mjs';
import { strRepr } from './pyrepr.mjs';
import { codePoints } from './pystr.mjs';
import { isAsciiWhitespace, isUnicodeWhitespace, decimalDigitValue } from './pyunicode.mjs';

function transformDecimalAndSpaceToAscii(s) {
  let out = '';

  for (const ch of codePoints(s)) {
    if (isUnicodeWhitespace(ch)) {
      out += ' ';
      continue;
    }
    const value = decimalDigitValue(ch.codePointAt(0));
    out += value >= 0 ? String(value) : ch;
  }

  return out;
}

function stripAsciiWhitespace(s) {
  let start = 0;
  let end = s.length;
  while (start < end && isAsciiWhitespace(s[start])) start++;
  while (end > start && isAsciiWhitespace(s[end - 1])) end--;
  return s.slice(start, end);
}

// A digit run may contain single underscores, but only between digits:
// '1_0' is valid, while '_10', '10_' and '1__0' are not.
const DIGIT_RUN = /^[0-9](?:_?[0-9])*$/;

/**
 * `int(text)`. Returns a BigInt, or throws PyValueError carrying CPython's
 * "invalid literal" message (which quotes the *original* text, not the
 * transformed one).
 */
export function pyInt(text) {
  const transformed = stripAsciiWhitespace(transformDecimalAndSpaceToAscii(text));

  let sign = 1n;
  let body = transformed;
  if (body.startsWith('+')) {
    body = body.slice(1);
  } else if (body.startsWith('-')) {
    sign = -1n;
    body = body.slice(1);
  }

  if (!DIGIT_RUN.test(body)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${strRepr(text)}`,
    );
  }

  return sign * BigInt(body.replace(/_/g, ''));
}
